/// <summary>
/// Copy/symlink boundary for an ignored overlay entry (64 MB). BELOW it an entry
/// is COPIED (writable + isolated → test writes stay in the sandboxed cwd); AT/ABOVE
/// it the entry is SYMLINKED (avoids copying huge read-mostly deps like node_modules).
/// </summary>
private const long IgnoredOverlayCopyMaxBytes = 64L * 1024 * 1024;

/// <summary>Maximum recursion depth for the per-entry overlay walk.</summary>
private const int MaxOverlayRecursionDepth = 16;

/// <summary>
/// Recursively overlays a git-ignored source directory into the verify worktree,
/// applying a per-entry copy-vs-symlink decision:
///   • Symlink entries (reparse points) → recreated as link nodes.
///   • Directories at/above <paramref name="thresholdBytes"/> → whole-dir symlink.
///   • Directories below the threshold → REAL directory, then recurse into children.
///   • Files at/above the threshold → file symlink; below → copy.
///
/// Recursion is bounded by <see cref="MaxOverlayRecursionDepth"/> and a per-top-level-
/// entry byte budget (<paramref name="thresholdBytes"/>). On hitting a bound, the
/// remaining subtree is symlinked and a <c>verify_overlay_skipped</c> warn event is
/// emitted. Every per-entry IO error is swallowed — the walk never aborts worktree
/// creation.
/// </summary>
private void OverlayIgnoredDirRecursive(
    string srcDir, string dstDir, long thresholdBytes, int depth,
    ref long copiedBytes, string topSourceDir, string topDestDir,
    string runId, string sourcePath, string worktreeId)
{
    // --- bounds checks (never apply at depth 0 — the top-level entry) ---
    if (depth > MaxOverlayRecursionDepth)
    {
        try { Directory.CreateSymbolicLink(dstDir, srcDir); } catch { }
        EmitOverlaySkipAdvisory(runId, sourcePath, worktreeId,
            Path.GetFileName(srcDir), "max_depth_exceeded");
        return;
    }
    if (depth > 0 && copiedBytes >= thresholdBytes)
    {
        try { Directory.CreateSymbolicLink(dstDir, srcDir); } catch { }
        EmitOverlaySkipAdvisory(runId, sourcePath, worktreeId,
            Path.GetFileName(srcDir), "copy_budget_exhausted");
        return;
    }
    if (depth > 0 && NonoRollbackSkipDirs.DirectoryMeetsSizeThreshold(srcDir, thresholdBytes))
    {
        try { Directory.CreateSymbolicLink(dstDir, srcDir); } catch { }
        return; // normal large-dir sharing — no event needed
    }

    // --- create the destination as a real directory ---
    Directory.CreateDirectory(dstDir);

    // --- enumerate children ---
    IEnumerable<FileSystemInfo> entries;
    try
    {
        var source = new DirectoryInfo(srcDir);
        if (!source.Exists) return;
        entries = source.EnumerateFileSystemInfos();
    }
    catch
    {
        return; // unauthorized / IO — leave the (empty) dest dir, never throw.
    }

    foreach (var entry in entries)
    {
        try
        {
            var childDst = Path.Combine(dstDir, entry.Name);

            // Reparse point (symlink) — recreate the link node, never follow.
            if ((entry.Attributes & FileAttributes.ReparsePoint) != 0)
            {
                RecreateSymlinkAt(entry, childDst, topSourceDir, topDestDir);
                continue;
            }

            if (entry is DirectoryInfo subDir)
            {
                OverlayIgnoredDirRecursive(subDir.FullName, childDst, thresholdBytes,
                    depth + 1, ref copiedBytes, topSourceDir, topDestDir,
                    runId, sourcePath, worktreeId);
            }
            else if (entry is FileInfo file)
            {
                if (file.Length >= thresholdBytes)
                    File.CreateSymbolicLink(childDst, file.FullName);
                else
                {
                    file.CopyTo(childDst, overwrite: false);
                    copiedBytes += file.Length;
                }
            }
        }
        catch
        {
            // Per-entry IO error — swallow, never abort.
        }
    }
}

/// <summary>
/// Recreates <paramref name="entry"/> as a symlink at <paramref name="destPath"/>,
/// rewriting absolute targets that fall inside <paramref name="topSourceDir"/> to
/// the corresponding path under <paramref name="topDestDir"/>. Relative targets and
/// absolute targets outside the top-level source are kept verbatim. Never follows
/// the link.
/// </summary>
private static void RecreateSymlinkAt(FileSystemInfo entry, string destPath,
    string topSourceDir, string topDestDir)
{
    string? linkTarget;
    try { linkTarget = entry.LinkTarget; }
    catch { return; }

    if (string.IsNullOrEmpty(linkTarget)) return;

    string resolvedTarget;
    if (Path.IsPathRooted(linkTarget))
    {
        var normalizedTarget = Path.GetFullPath(linkTarget);
        var normalizedSource = Path.GetFullPath(topSourceDir);
        if (normalizedTarget.StartsWith(normalizedSource + Path.DirectorySeparatorChar)
            || normalizedTarget == normalizedSource)
        {
            resolvedTarget = Path.GetFullPath(Path.Combine(
                topDestDir, normalizedTarget[(normalizedSource.Length + 1)..]));
        }
        else
        {
            resolvedTarget = linkTarget; // outside sourceDir — verbatim
        }
    }
    else
    {
        resolvedTarget = linkTarget; // relative — verbatim
    }

    if (entry is DirectoryInfo)
        Directory.CreateSymbolicLink(destPath, resolvedTarget);
    else
        File.CreateSymbolicLink(destPath, resolvedTarget);
}

/// <summary>
/// Fire-and-forget, best-effort publish of a <c>verify_overlay_skipped</c>
/// warn event. Failure to publish is silently swallowed.
/// </summary>
private void EmitOverlaySkipAdvisory(string runId, string sourcePath, string worktreeId,
    string entry, string reason)
{
    try
