// ───────────────────────────────────────────────────────────────────
// 13. Bounded recursion fallback: many tiny files in sibling subtrees
//     cumulatively exhaust the per-top-level-entry byte budget. The
//     remaining subtree is symlinked and a verify_overlay_skipped warn
//     event with reason "copy_budget_exhausted" is published.
// ───────────────────────────────────────────────────────────────────

[Fact]
public async Task CreateVerifyWorktree_BudgetExhausted_SymlinksRemainingSubtreeAndEmitsWarn()
{
    var root = Path.Combine(Path.GetTempPath(), "vr-vw-budget-" + Guid.NewGuid().ToString("N"));
    Directory.CreateDirectory(root);
    var sink = new InMemoryRelayEventSink();
    var driver = new RelayDriver(RelayDriverDependencies.ForTests(
        new ScriptedSubagentRunner(), new ScriptedTestRunner(), sink, new GitSimEngine()));
    string? worktree = null;
    try
    {
        InitRepo(root);
        await File.WriteAllTextAsync(Path.Combine(root, ".gitignore"), "deps/\n");
        await File.WriteAllTextAsync(Path.Combine(root, "tracked.txt"), "tracked");

        // deps/a/ — two files that together reach the threshold.
        Directory.CreateDirectory(Path.Combine(root, "deps", "a"));
        await File.WriteAllBytesAsync(
            Path.Combine(root, "deps", "a", "file1.bin"),
            new byte[LowThresholdBytes / 2]);
        await File.WriteAllBytesAsync(
            Path.Combine(root, "deps", "a", "file2.bin"),
            new byte[LowThresholdBytes / 2]);

        // deps/b/ — sibling dir processed after the budget is exhausted;
        // its size is below threshold so the budget check catches it.
        Directory.CreateDirectory(Path.Combine(root, "deps", "b"));
        await File.WriteAllTextAsync(
            Path.Combine(root, "deps", "b", "late.txt"), "late");

        await CommitAll(root, "seed");

        worktree = await driver.CreateVerifyWorktreeForTestAsync(
            root, "task-budget", "run-budget", CancellationToken.None, LowThresholdBytes);

        // Worktree creation must still succeed (the fallback never aborts).
        Assert.True(Directory.Exists(worktree), "worktree must be created");

        // deps/ itself is a real dir.
        var depsDir = Path.Combine(worktree, "deps");
        Assert.True(Directory.Exists(depsDir));
        Assert.False(new DirectoryInfo(depsDir).Attributes.HasFlag(FileAttributes.ReparsePoint));

        // A verify_overlay_skipped warn event with reason "copy_budget_exhausted"
        // must have been published.
        var budgetWarn = sink.Events.FirstOrDefault(e =>
            e.Level == "warn"
            && e.EventName == "verify_overlay_skipped"
            && e.Data != null
            && e.Data.TryGetValue("reason", out var r)
            && r == "copy_budget_exhausted");
        Assert.NotNull(budgetWarn);
        Assert.NotNull(budgetWarn!.Data);
        Assert.True(budgetWarn.Data!.ContainsKey("entry"),
            "warn event data must name the entry that was skipped");
    }
    finally
    {
        if (worktree is not null)
            await driver.CleanupVerifyWorktreeForTestAsync(root, worktree, CancellationToken.None);
        TestFileSystem.DeleteDirectoryResilient(root);
    }
}

